package com.guocheng.mediapocket;
import java.net.*;import java.io.*;import java.util.*;
final class SubtitleHttp {
 static byte[] download(String raw,Map<String,String> extra)throws Exception{TvPosterRules.Picture p=TvPosterRules.parse(raw);URL u=new URL(p.url);if(!u.getProtocol().equals("http")&&!u.getProtocol().equals("https"))throw new IOException("字幕地址类型不支持");Map<String,String> headers=new LinkedHashMap<>(p.headers);if(extra!=null)for(Map.Entry<String,String> h:extra.entrySet()){String n=h.getKey(),v=h.getValue();if(!(n.equalsIgnoreCase("Referer")||n.equalsIgnoreCase("User-Agent")||n.equalsIgnoreCase("Origin")||n.equalsIgnoreCase("Accept")))continue;if(v.indexOf('\r')>=0||v.indexOf('\n')>=0||v.indexOf('\0')>=0)throw new IOException("非法字幕请求头");headers.put(n,v);}HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);for(Map.Entry<String,String> h:headers.entrySet())c.setRequestProperty(h.getKey(),h.getValue());try{int status=c.getResponseCode();if(status!=200)throw new IOException("HTTP "+status);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>2*1024*1024)throw new IOException("字幕文件过大");out.write(b,0,n);}return out.toByteArray();}}finally{c.disconnect();}}
}
